func fleetCountLabel(total int64) string { return fmt.Sprintf("%d", total) }

func fleetStatusLabel(status string) string {
	switch status {
	case "Operational":
		return "Operacional"
	case "Maintenance", "Scheduled":
		return "Manutenção"
	case "Retired":
		return "Retirado"
	case "Pendente":
		return "Pendente"
	case "Em_Analise":
		return "Em análise"
	case "Resolvido", "Completed":
		return "Concluído"
	case "In_Progress":
		return "Em curso"
	default:
		return status
	}
}

func fleetStatusTone(status string) string {
	switch status {
	case "Operational", "Resolvido", "Completed":
		return "success"
	case "Maintenance", "Scheduled", "Em_Analise", "In_Progress":
		return "warning"
	case "Retired":
		return "error"
	default:
		return "selected"
	}
}

func equipmentTypeLabel(value string) string {
	switch value {
	case "Boat":
		return "Embarcação"
	case "Paddle":
		return "Pagaia"
	case "Vehicle":
		return "Veículo"
	default:
		return value
	}
}

